1	// Combines local provider pricing + Artificial Analysis benchmark data into
2	// per-category recommendations.
3	
4	import { readFile, writeFile, mkdir } from "node:fs/promises";
5	import path from "node:path";
6	import { pricingSources } from "../pricing/sources.ts";
7	
8	// A PricingSource id, e.g. "copilot".
9	export type Provider = string;
10	
11	interface Candidate {
12	  provider: Provider;
13	  model: string;
14	  priceInput: number;
15	  priceOutput: number;
16	}
17	
18	export interface MappingEntry {
19	  provider: Provider;
20	  providerModel: string;
21	  aaSlug: string | null;
22	  note?: string;
23	}
24	
25	// Free-tier row from /language/models/free. Since Intelligence Index v5 Artificial
26	// Analysis no longer publishes a Coding or Agentic Index (those fields are always null),
27	// so they're not read here.
28	export interface AaModel {
29	  id: string;
30	  name: string;
31	  slug: string;
32	  evaluations: {
33	    artificial_analysis_intelligence_index?: number | null;
34	  };
35	  // What one Intelligence Index task cost to run at AA's prices; it reflects how many
36	  // tokens the model actually spends, not just its per-token price.
37	  artificial_analysis_intelligence_index_cost?: {
38	    cost_per_task?: { total_cost?: number | null } | null;
39	  } | null;
40	  pricing?: {
41	    price_1m_input_tokens?: number | null;
42	    price_1m_output_tokens?: number | null;
43	  } | null;
44	  performance?: {
45	    median_output_tokens_per_second?: number | null;
46	  } | null;
47	  performance_v3?: {
48	    mean_output_tokens_per_second?: number | null;
49	  } | null;
50	}
51	
52	type Metric = "intelligenceIndex" | "costEfficiency" | "speed";
53	
54	const METRICS: Metric[] = ["intelligenceIndex", "costEfficiency", "speed"];
55	
56	type CategoryWeights = Partial<Record<Metric, number>>;
57	
58	interface CategoryConfig {
59	  description?: string;
60	  outputToInputRatio?: number;
61	  weights: CategoryWeights;
62	}
63	
64	interface CategoriesConfig {
65	  topNPerProvider: number;
66	  expectedIntelligenceIndexVersion: number;
67	  categories: Record<string, CategoryConfig>;
68	}
69	
70	interface BlacklistEntry {
71	  match: string;
72	  reason: string;
73	}
74	
75	interface ScoredCandidate {
76	  provider: Provider;
77	  model: string;
78	  aaSlug: string;
79	  score: number;
80	  breakdown: {
81	    intelligenceIndex: number;
82	    speed: number;
83	    // Estimated USD for one Intelligence Index task at this provider's prices.
84	    costPerTask: number;
85	  };
86	  priceBlendedPer1M: number;
87	}
88	
89	// Default output tokens per 1 input token (typical agentic coding workload). A category can
90	// override it with outputToInputRatio in config/categories.json.
91	const DEFAULT_OUTPUT_TO_INPUT_RATIO = 3;
92	
93	function blendedPrice(
94	  priceInput: number,
95	  priceOutput: number,
96	  outputToInputRatio: number = DEFAULT_OUTPUT_TO_INPUT_RATIO,
97	): number {
98	  const totalParts = 1 + outputToInputRatio;
99	  return (priceInput * 1 + priceOutput * outputToInputRatio) / totalParts;
100	}
101	
102	// Strips variant qualifiers like " (<= 256K tokens)", " (Off-Peak)", " (Peak)" so
103	// tiered/peak pricing rows collapse to one representative candidate per base model.
104	export function baseModelName(model: string): string {
105	  let stripped = model;
106	  while (/\s*\([^)]*\)\s*$/.test(stripped)) {
107	    stripped = stripped.replace(/\s*\([^)]*\)\s*$/, "").trim();
108	  }
109	  return stripped;
110	}
111	
112	function dedupeCheapest(
113	  rows: { model: string; priceInput: number; priceOutput: number }[],
114	): { model: string; priceInput: number; priceOutput: number }[] {
115	  const byBase = new Map<string, { model: string; priceInput: number; priceOutput: number }>();
116	  for (const row of rows) {
117	    const base = baseModelName(row.model);
118	    const existing = byBase.get(base);
119	    if (
120	      !existing ||
121	      blendedPrice(row.priceInput, row.priceOutput) <
122	        blendedPrice(existing.priceInput, existing.priceOutput)
123	    ) {
124	      byBase.set(base, { model: base, priceInput: row.priceInput, priceOutput: row.priceOutput });
125	    }
126	  }
127	  return [...byBase.values()];
128	}
129	
130	export async function loadCandidates(): Promise<Candidate[]> {
131	  const candidates: Candidate[] = [];
132	  for (const source of pricingSources) {
133	    let raw: { models: Record<string, unknown>[] };
134	    try {
135	      raw = JSON.parse(await readFile(source.outFile, "utf8"));
136	    } catch (err) {
137	      // A provider whose parser has never succeeded has no data yet; score the others.
138	      if ((err as NodeJS.ErrnoException).code !== "ENOENT") throw err;
139	      console.warn(
140	        `No ${source.displayName} pricing data at ${source.outFile}; skipping provider.`,
141	      );
142	      continue;
143	    }
144	
145	    const { input, output } = source.priceFields;
146	    const rows = dedupeCheapest(
147	      raw.models.map((m) => ({
148	        model: m.model as string,
149	        priceInput: m[input] as number,
150	        priceOutput: m[output] as number,
151	      })),
152	    );
153	    candidates.push(...rows.map((r) => ({ provider: source.id, ...r })));
154	  }
155	  return candidates;
156	}
157	
158	function normalize(value: number, min: number, max: number): number {
159	  if (max === min) return 1;
160	  return (value - min) / (max - min);
161	}
162	
163	// Fails loudly on config that no longer matches the data, instead of publishing
164	// rankings where a weighted metric silently scores nothing (which happened when AA
165	// dropped the Coding and Agentic indexes).
166	function validateConfig(config: CategoriesConfig, aaVersion: unknown): void {
167	  if (aaVersion !== config.expectedIntelligenceIndexVersion) {
168	    throw new Error(
169	      `Artificial Analysis reports Intelligence Index version ${String(aaVersion)}, but config/categories.json expects ${config.expectedIntelligenceIndexVersion}. ` +
170	        "Check the API docs for changed or removed fields, adjust scoring, then update expectedIntelligenceIndexVersion.",
171	    );
172	  }
173	  for (const [name, category] of Object.entries(config.categories)) {
174	    const unknown = Object.keys(category.weights).filter((k) => !METRICS.includes(k as Metric));
175	    if (unknown.length > 0) {
176	      throw new Error(
177	        `Category "${name}" weights unknown metrics: ${unknown.join(", ")}. Known metrics: ${METRICS.join(", ")}.`,
178	      );
179	    }
180	  }
181	}
182	
183	export async function computeScores(): Promise<void> {
184	  const config: CategoriesConfig = JSON.parse(
185	    await readFile(path.join("config", "categories.json"), "utf8"),
186	  );
187	  const blacklist: BlacklistEntry[] = JSON.parse(
188	    await readFile(path.join("config", "blacklist.json"), "utf8"),
189	  );
190	  const aaData = JSON.parse(
191	    await readFile(path.join("data", "artificial-analysis", "language-models.json"), "utf8"),
192	  );
193	  validateConfig(config, aaData.intelligenceIndexVersion);
194	
195	  const allCandidates = await loadCandidates();
196	
197	  const candidates = allCandidates.filter((c) => {
198	    const hit = blacklist.find((b) => c.model.toLowerCase().includes(b.match.toLowerCase()));
199	    if (hit) {
200	      console.warn(`Blacklisted ${c.provider}/${c.model}: ${hit.reason}`);
201	      return false;
202	    }
203	    return true;
204	  });
205	
206	  const mapping: MappingEntry[] = JSON.parse(
207	    await readFile(path.join("config", "model-mapping.json"), "utf8"),
208	  );
209	  const aaBySlug = new Map<string, AaModel>((aaData.models as AaModel[]).map((m) => [m.slug, m]));
210	
211	  const enriched: {
212	    provider: Provider;
213	    model: string;
214	    aaSlug: string;
215	    intelligenceIndex: number;
216	    speed: number;
217	    aaCostPerTask: number;
218	    aaPriceInput: number;
219	    aaPriceOutput: number;
220	    priceInput: number;
221	    priceOutput: number;
222	  }[] = [];
223	
224	  for (const candidate of candidates) {
225	    const label = `${candidate.provider}/${candidate.model}`;
226	    if (blendedPrice(candidate.priceInput, candidate.priceOutput) <= 0) {
227	      // Cost efficiency is 1 / cost, so free models would be infinitely efficient.
228	      console.warn(`Skipping ${label}: free model, not scored.`);
229	      continue;
230	    }
231	
232	    const map = mapping.find(
233	      (m) => m.provider === candidate.provider && m.providerModel === candidate.model,
234	    );
235	    if (!map || !map.aaSlug) {
236	      console.warn(`Skipping ${label}: no Artificial Analysis mapping.`);
237	      continue;
238	    }
239	    const aa = aaBySlug.get(map.aaSlug);
240	    if (!aa) {
241	      console.warn(`Skipping ${label}: aaSlug "${map.aaSlug}" not found in fetched data.`);
242	      continue;
243	    }
244	
245	    // Every scored model needs all inputs; nothing is estimated or zero-filled.
246	    const intelligenceIndex = aa.evaluations.artificial_analysis_intelligence_index ?? null;
247	    const speed =
248	      aa.performance?.median_output_tokens_per_second ??
249	      aa.performance_v3?.mean_output_tokens_per_second ??
250	      null;
251	    const aaCostPerTask =
252	      aa.artificial_analysis_intelligence_index_cost?.cost_per_task?.total_cost ?? null;
253	    const aaPriceInput = aa.pricing?.price_1m_input_tokens ?? null;
254	    const aaPriceOutput = aa.pricing?.price_1m_output_tokens ?? null;
255	    const missing = [
256	      intelligenceIndex == null && "intelligence index",
257	      speed == null && "speed",
258	      aaCostPerTask == null && "cost per task",
259	      (aaPriceInput == null ||
260	        aaPriceOutput == null ||
261	        blendedPrice(aaPriceInput, aaPriceOutput) <= 0) &&
262	        "AA pricing",
263	    ].filter((m): m is string => typeof m === "string");
264	    if (missing.length > 0) {
265	      console.warn(`Skipping ${label} ("${map.aaSlug}"): no ${missing.join(", ")}.`);
266	      continue;
267	    }
268	
269	    enriched.push({
270	      provider: candidate.provider,
271	      model: candidate.model,
272	      aaSlug: map.aaSlug,
273	      intelligenceIndex: intelligenceIndex!,
274	      speed: speed!,
275	      aaCostPerTask: aaCostPerTask!,
276	      aaPriceInput: aaPriceInput!,
277	      aaPriceOutput: aaPriceOutput!,
278	      priceInput: candidate.priceInput,
279	      priceOutput: candidate.priceOutput,
280	    });
281	  }
282	
283	  if (enriched.length === 0) {
284	    throw new Error(
285	      "No candidates have complete benchmark data; refusing to publish empty rankings.",
286	    );
287	  }
288	
289	  const categories: Record<string, Record<Provider, ScoredCandidate[]>> = {};
290	
291	  for (const [categoryName, categoryConfig] of Object.entries(config.categories)) {
292	    const weights = categoryConfig.weights;
293	    const ratio = categoryConfig.outputToInputRatio ?? DEFAULT_OUTPUT_TO_INPUT_RATIO;
294	
295	    const blendedPrices = enriched.map((e) => blendedPrice(e.priceInput, e.priceOutput, ratio));
296	    // Scale AA's measured cost per task by how this provider's price compares to AA's,
297	    // so a model that's cheap per token but verbose isn't mistaken for a cheap one.
298	    const costsPerTask = enriched.map(
299	      (e, i) =>
300	        (e.aaCostPerTask * blendedPrices[i]) / blendedPrice(e.aaPriceInput, e.aaPriceOutput, ratio),
301	    );
302	    const values: Record<Metric, number[]> = {
303	      intelligenceIndex: enriched.map((e) => e.intelligenceIndex),
304	      speed: enriched.map((e) => e.speed),
305	      costEfficiency: costsPerTask.map((c) => 1 / c),
306	    };
307	    const normalized = Object.fromEntries(
308	      METRICS.map((m) => {
309	        const min = Math.min(...values[m]);
310	        const max = Math.max(...values[m]);
311	        return [m, values[m].map((v) => normalize(v, min, max))];
312	      }),
313	    ) as Record<Metric, number[]>;
314	
315	    const scored: ScoredCandidate[] = enriched.map((e, i) => {
316	      const score = METRICS.reduce((sum, m) => sum + (weights[m] ?? 0) * normalized[m][i], 0);
317	      return {
318	        provider: e.provider,
319	        model: e.model,
320	        aaSlug: e.aaSlug,
321	        score: Math.round(score * 1000) / 1000,
322	        breakdown: {
323	          intelligenceIndex: e.intelligenceIndex,
324	          speed: e.speed,
325	          costPerTask: Math.round(costsPerTask[i] * 10000) / 10000,
326	        },
327	        priceBlendedPer1M: Math.round(blendedPrices[i] * 1000) / 1000,
328	      };
329	    });
330	
331	    scored.sort((a, b) => b.score - a.score);
332	
333	    categories[categoryName] = Object.fromEntries(
334	      pricingSources.map((source) => [
335	        source.id,
336	        scored.filter((s) => s.provider === source.id).slice(0, config.topNPerProvider),
337	      ]),
338	    );
339	  }
340	
341	  const outFile = path.join("data", "recommendations.json");
342	  await mkdir(path.dirname(outFile), { recursive: true });
343	  await writeFile(
344	    outFile,
345	    JSON.stringify(
346	      {
347	        generatedAt: new Date().toISOString(),
348	        topNPerProvider: config.topNPerProvider,
349	        candidatesConsidered: enriched.length,
350	        intelligenceIndexVersion: aaData.intelligenceIndexVersion,
351	        categories,
352	      },
353	      null,
354	      2,
355	    ),
356	  );
357	
358	  console.log(
359	    `Wrote recommendations for ${Object.keys(categories).length} categories (${enriched.length} scored candidates) to ${outFile}`,
360	  );
361	}
