1	// Fetches Artificial Analysis language model benchmark data. Requires AA_API_KEY
2	// in the environment (see .env.example).
3	
4	import { readFile, writeFile, mkdir } from "node:fs/promises";
5	import path from "node:path";
6	
7	const API_BASE = "https://artificialanalysis.ai/api/v2";
8	const OUT_FILE = path.join("data", "artificial-analysis", "language-models.json");
9	
10	async function readCached(): Promise<{
11	  fetchedAt: string;
12	  modelCount: number;
13	  servedBy: string;
14	} | null> {
15	  try {
16	    const raw = JSON.parse(await readFile(OUT_FILE, "utf8"));
17	    return { fetchedAt: raw.fetchedAt, modelCount: raw.modelCount, servedBy: raw.servedBy };
18	  } catch (err) {
19	    if ((err as NodeJS.ErrnoException).code === "ENOENT") return null;
20	    throw err;
21	  }
22	}
23	
24	async function fetchAllPages(
25	  endpointPath: string,
26	  apiKey: string,
27	): Promise<{ tier: string; intelligenceIndexVersion: number; rows: unknown[] }> {
28	  const rows: unknown[] = [];
29	  let page = 1;
30	  let tier = "";
31	  let intelligenceIndexVersion = 0;
32	
33	  while (true) {
34	    const url = `${API_BASE}${endpointPath}?page=${page}`;
35	    const res = await fetch(url, { headers: { "x-api-key": apiKey } });
36	
37	    if (!res.ok) {
38	      const body = await res.text();
39	      throw Object.assign(new Error(`${res.status} ${res.statusText} on ${url}: ${body}`), {
40	        status: res.status,
41	      });
42	    }
43	
44	    const json = await res.json();
45	    tier = json.tier;
46	    intelligenceIndexVersion = json.intelligence_index_version;
47	    rows.push(...json.data);
48	
49	    if (!json.pagination?.has_more) break;
50	    page += 1;
51	  }
52	
53	  return { tier, intelligenceIndexVersion, rows };
54	}
55	
56	export async function fetchArtificialAnalysisData(): Promise<void> {
57	  const apiKey = process.env.AA_API_KEY;
58	  if (!apiKey) {
59	    throw new Error("Missing AA_API_KEY. Copy .env.example to .env and fill in your key.");
60	  }
61	
62	  let result: { tier: string; intelligenceIndexVersion: number; rows: unknown[] };
63	  let servedBy = "/language/models";
64	
65	  // A previous run already learned this key can't reach the Pro+ endpoint, so go
66	  // straight to the free one instead of spending a request on a guaranteed 403.
67	  const cachedTier = await readCached();
68	  if (cachedTier?.servedBy === "/language/models/free") {
69	    servedBy = "/language/models/free";
70	  }
71	
72	  try {
73	    try {
74	      result = await fetchAllPages(servedBy, apiKey);
75	    } catch (err) {
76	      if (servedBy === "/language/models" && (err as { status?: number }).status === 403) {
77	        console.log(
78	          "Key tier does not cover /language/models (Pro+), falling back to /language/models/free ...",
79	        );
80	        servedBy = "/language/models/free";
81	        result = await fetchAllPages("/language/models/free", apiKey);
82	      } else {
83	        throw err;
84	      }
85	    }
86	  } catch (err) {
87	    // Rate limited: keep whatever data is already on disk (seeded from the previous run)
88	    // rather than failing the whole pipeline. Only bail out if there's nothing to fall back to.
89	    if ((err as { status?: number }).status === 429) {
90	      if (cachedTier) {
91	        console.warn(
92	          `Rate limited by Artificial Analysis; keeping cached data from ${cachedTier.fetchedAt} (${cachedTier.modelCount} models).`,
93	        );
94	        return;
95	      }
96	    }
97	    throw err;
98	  }
99	
100	  await mkdir(path.dirname(OUT_FILE), { recursive: true });
101	  await writeFile(
102	    OUT_FILE,
103	    JSON.stringify(
104	      {
105	        sourceUrl: `${API_BASE}${servedBy}`,
106	        servedBy,
107	        fetchedAt: new Date().toISOString(),
108	        tier: result.tier,
109	        intelligenceIndexVersion: result.intelligenceIndexVersion,
110	        modelCount: result.rows.length,
111	        models: result.rows,
112	      },
113	      null,
114	      2,
115	    ),
116	  );
117	
118	  console.log(`Wrote ${result.rows.length} models (tier: ${result.tier}) to ${OUT_FILE}`);
119	}
