import { readFileSync } from "node:fs";
const aa = JSON.parse(readFileSync(process.argv[2], "utf8")).models;
const keys = [
  "intelligence",
  "engineering",
  "finance_and_accounting",
  "strategy_and_ops",
  "legal",
  "healthcare_and_medical",
  "economics",
];
const get = (m, k) => m.evaluations[`artificial_analysis_${k}_index`];
const corr = (a, b) => {
  const n = a.length;
  const ma = a.reduce((x, y) => x + y) / n;
  const mb = b.reduce((x, y) => x + y) / n;
  let s = 0,
    sa = 0,
    sb = 0;
  for (let i = 0; i < n; i++) {
    s += (a[i] - ma) * (b[i] - mb);
    sa += (a[i] - ma) ** 2;
    sb += (b[i] - mb) ** 2;
  }
  return s / Math.sqrt(sa * sb);
};
console.log("pairwise r (n):");
for (const a of keys) {
  const row = keys.map((b) => {
    const ms = aa.filter((m) => get(m, a) != null && get(m, b) != null);
    return (
      corr(
        ms.map((m) => get(m, a)),
        ms.map((m) => get(m, b)),
      ).toFixed(3) + `(${ms.length})`
    );
  });
  console.log(a.padEnd(24), row.join(" "));
}
// How much does each domain index deviate from what intelligence predicts? (residual SD in points)
for (const k of keys.slice(1)) {
  const ms = aa.filter((m) => get(m, "intelligence") != null && get(m, k) != null);
  const x = ms.map((m) => get(m, "intelligence"));
  const y = ms.map((m) => get(m, k));
  const n = x.length;
  const mx = x.reduce((p, q) => p + q) / n;
  const my = y.reduce((p, q) => p + q) / n;
  const b = x.reduce((s, v, i) => s + (v - mx) * (y[i] - my), 0) / x.reduce((s, v) => s + (v - mx) ** 2, 0);
  const res = ms.map((m, i) => ({ name: m.name, r: y[i] - (my + b * (x[i] - mx)) }));
  const sd = Math.sqrt(res.reduce((s, v) => s + v.r ** 2, 0) / n);
  res.sort((p, q) => q.r - p.r);
  console.log(
